<template>
	<view class="adopt-page page-container">
		<!-- 顶部栏 -->
		<view class="header">
			<view class="city-select">
				<text class="city-text">{{ currentCity }}</text>
				<text class="arrow">▼</text>
			</view>
			<view class="search-icon" @click="handleSearch">
				<text>🔍</text>
			</view>
		</view>

		<!-- 标题 -->
		<view class="title-section">
			<text class="main-title">等待回家的小伙伴</text>
			<text class="sub-title">每一次了解，都是靠近彼此的一步</text>
		</view>

		<!-- 分类Tab -->
		<view class="tab-list">
			<view 
				class="tab-item" 
				:class="{ active: currentTab === item.value }"
				v-for="item in tabList" 
				:key="item.value"
				@click="changeTab(item.value)"
			>
				{{ item.label }}
			</view>
		</view>

		<!-- 宠物列表 -->
		<view class="pet-grid">
			<view class="pet-card" v-for="item in filteredList" :key="item.id" @click="goDetail(item.id)">
				<view class="card-img-wrap">
					<image class="pet-img" :src="item.avatar" mode="aspectFill" />
					<view class="more-btn">
						<text>∨</text>
					</view>
				</view>
				<view class="card-content">
					<view class="pet-header">
						<text class="pet-name">{{ item.name }}</text>
						<text class="heart-icon" :class="{ liked: item.isLiked }" @click.stop="toggleLike(item)">♥</text>
					</view>
					<text class="pet-desc">{{ item.age }} | {{ item.character }} | 现处{{ item.location }}</text>
					<view class="card-footer">
						<view class="stats">
							<text class="stat-item">
								<text class="stat-icon">⭐</text>
								{{ item.star }}
							</text>
							<text class="stat-item">
								<text class="stat-icon">💬</text>
								{{ item.comment }}
							</text>
						</view>
						<view class="apply-btn" @click.stop="applyAdopt(item)">
							申请领养
						</view>
					</view>
				</view>
			</view>
		</view>
	</view>
</template>

<script setup>
import { ref, computed } from 'vue'

const currentCity = ref('北京')
const currentTab = ref('all')

// 分类tab
const tabList = ref([
	{ label: '全部', value: 'all' },
	{ label: '猫咪', value: 'cat' },
	{ label: '狗狗', value: 'dog' },
	{ label: '小型宠', value: 'small' },
	{ label: '已到家', value: 'adopted' }
])

// 测试数据 - 宠物列表
const petList = ref([
	{
		id: 1,
		name: '布丁',
		type: 'cat',
		age: '2岁',
		character: '聪明 安静',
		location: '南京',
		avatar: 'https://picsum.photos/id/40/400/500',
		star: 35,
		comment: 146,
		isLiked: false
	},
	{
		id: 2,
		name: '阿宝',
		type: 'cat',
		age: '2岁半',
		character: '黏人 好动',
		location: '苏州',
		avatar: 'https://picsum.photos/id/41/400/500',
		star: 35,
		comment: 196,
		isLiked: true
	},
	{
		id: 3,
		name: '可乐',
		type: 'dog',
		age: '3岁',
		character: '聪明 调皮',
		location: '长沙',
		avatar: 'https://picsum.photos/id/237/400/500',
		star: 21,
		comment: 1146,
		isLiked: false
	},
	{
		id: 4,
		name: '柴柴',
		type: 'dog',
		age: '1岁半',
		character: '内敛 安静',
		location: '北京',
		avatar: 'https://picsum.photos/id/169/400/500',
		star: 90,
		comment: 45,
		isLiked: false
	}
])

// 筛选后的列表
const filteredList = computed(() => {
	if (currentTab.value === 'all') return petList.value
	return petList.value.filter(item => item.type === currentTab.value)
})

// 切换tab
const changeTab = (val) => {
	currentTab.value = val
}

// 切换收藏
const toggleLike = (item) => {
	item.isLiked = !item.isLiked
}

// 申请领养
const applyAdopt = (item) => {
	uni.showToast({
		title: `已提交${item.name}的领养申请`,
		icon: 'success'
	})
}

// 跳转详情
const goDetail = (id) => {
	uni.navigateTo({ url: `/pages/adopt-detail/adopt-detail?id=${id}` })
}

const handleSearch = () => {
	uni.showToast({ title: '搜索功能', icon: 'none' })
}
</script>

